--!strict
-- Editor help and autocomplete. Runtime checks still validate every supplied value.
export type State = {[string]: boolean | number | string}
export type Volume = {kind: "box", frame: CFrame, size: Vector3}
	| {kind: "sphere", frame: CFrame, radius: number}
	| {kind: "capsule", frame: CFrame, radius: number, height: number}
export type Sweep = {kind: "sweep", start: Vector3, finish: Vector3, radius: number}
export type Snapshot = {root: CFrame, zones: {[string]: Volume}, state: State?}
export type Binding = {
	kind: string,
	capture: (serverTime: number) -> Snapshot,
	trust: ("unverified" | "serverSimulated" | "serverValidated")?,
	maxSpeed: number,
	maxRadius: number,
}
export type Profile = {
	shape: Volume | Sweep,
	targets: {string},
	opens: number?,
	closes: number?,
	maxTargets: number?,
	maxReach: number?,
	eligible: ((source: State, target: State, targetId: string, targetKind: string) -> boolean)?,
	world: boolean?,
}
-- Keep the value BeginAction returns; do not make your own table for a move reference.
export type Move = {}
export type Contact = {id: string, kind: string, zone: string, time: number, epoch: number,
	state: State, root: CFrame, distance: number, fraction: number}
export type Result = {ok: boolean, reason: string, contacts: {Contact}, time: number?,
	capturedAt: number?, rewind: number?, source: any?, shape: (Volume | Sweep)?, actor: string?}
export type CaptureResult = {ok: boolean, reason: string, time: number?,
	faults: {{id: string, reason: string}}?, contacts: {Contact}}
export type Options = {
	seconds: number?, rate: number?, maxGap: number?, maxRewind: number?,
	clock: (() -> number)?,
	resolveRewind: ((actorId: string, approvedServerContext: any, captureTime: number) -> number)?,
	world: ((queryTime: number, now: number, shape: Sweep) -> {covered: boolean, blocked: boolean?, fraction: number?})?,
}
export type Explanation = {code: string, known: boolean, subject: string?, title: string, meaning: string, fix: string}
export type Service = {
	Track: (self: Service, id: string, binding: Binding) -> (),
	Untrack: (self: Service, id: string) -> boolean,
	Discontinuity: (self: Service, id: string, reason: string?) -> (),
	Capture: (self: Service, serverTime: number?) -> CaptureResult,
	BeginAction: (self: Service, actorId: string, profile: Profile, approvedServerContext: any?) -> (Move?, string?),
	Query: (self: Service, move: Move) -> Result,
	EndAction: (self: Service, move: Move) -> boolean,
	Inspect: (self: Service) -> any,
	Destroy: (self: Service) -> (),
}
return table.freeze({})

-- Modular counters for state packets; lifetimes and owners are separate counters.
local S = {MOD = 4294967296, HALF = 2147483648}
function S.Newer(value, previous)
	if type(value) ~= "number" or value % 1 ~= 0 or value < 0 or value >= S.MOD then return false end
	if previous == nil then return true end
	local delta = (value - previous) % S.MOD
	return delta > 0 and delta < S.HALF
end
function S.Next(value) return ((value or 0) + 1) % S.MOD end
return table.freeze(S)

const Config = require(script.Parent.Config)

type level = Config.WarningLevels

const function checkLevel(level: level): boolean
	const levels: { [level]: number } = {
		NONE = 0,
		LOW = 1,
		MEDIUM = 2,
		HIGH = 3,
	}
	const currentLevel = levels[Config._GetConfig("WARNING_SEVERITY") :: level] or 0
	if currentLevel == 0 then
		return false
	end
	const checkAgainst = levels[level] or 0
	return currentLevel <= checkAgainst
end

const function noop(...: any) end
const warnAny: (...any) -> () = warn

-- Designed it this way so the first message leads to the place the function was called.
return (
	setmetatable({}, {
		__index = function(_, level: level): (...any) -> ()
			if not checkLevel(level:upper() :: any) then
				return noop
			end
			return warnAny
		end,
	}) :: any
) :: {
	low: (...any) -> (),
	medium: (...any) -> (),
	high: (...any) -> (),
}

-- Four-timestamp exchange bounds offset without pretending RTT/2 is measured one-way latency.
local C = {}
local function finite(x) return type(x)=="number" and x==x and math.abs(x)<math.huge end
function C.Exchange(clientSend,serverReceive,serverSend,clientReceive)
	if not finite(clientSend) or not finite(serverReceive) or not finite(serverSend) or not finite(clientReceive) then return nil,"clock_numeric" end
	if clientReceive<clientSend or serverSend<serverReceive then return nil,"clock_order" end
	local rtt=(clientReceive-clientSend)-(serverSend-serverReceive)
	if rtt<0 then return nil,"clock_order" end
	local lower,upper=serverSend-clientReceive,serverReceive-clientSend
	if not finite(rtt) or not finite(lower) or not finite(upper) or not finite((lower+upper)/2) then return nil,"clock_numeric" end
	return table.freeze({lower=lower,upper=upper,estimate=(lower+upper)/2,uncertainty=(upper-lower)/2,rtt=rtt})
end
function C.Map(bounds,clientTime,maximumAge,serverNow)
	if type(bounds)~="table" or not finite(bounds.lower) or not finite(bounds.upper) or bounds.lower>bounds.upper
		or not finite(clientTime) or not finite(serverNow) or not finite(maximumAge) or maximumAge<0 then return nil,"clock_numeric" end
	local lower,upper=clientTime+bounds.lower,clientTime+bounds.upper
	if upper>serverNow+1e-6 or lower<serverNow-maximumAge then return nil,"clock_out_of_policy" end
	return table.freeze({time=(lower+upper)/2,lower=lower,upper=upper,uncertainty=(upper-lower)/2})
end
return table.freeze(C)

